const DB_NAME='studymate-local-db', DB_STORE='workspace', DB_KEY='primary';
let dbWriteQueue=Promise.resolve();
function openStudyDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window)){reject(new Error('IndexedDB kullanılamıyor.'));return}const r=indexedDB.open(DB_NAME,2);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains(DB_STORE))r.result.createObjectStore(DB_STORE);if(!r.result.objectStoreNames.contains('files'))r.result.createObjectStore('files')};r.onblocked=()=>reject(new Error('Veritabanı başka bir açık pencerede güncelleniyor. Diğer StudyMate pencerelerini kapatıp tekrar dene.'));r.onerror=()=>reject(r.error||new Error('IndexedDB açılamadı.'));r.onsuccess=()=>{const db=r.result;db.onversionchange=()=>db.close();resolve(db)}})}
async function readStudyDB(){const db=await openStudyDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readonly'),r=tx.objectStore(DB_STORE).get(DB_KEY);r.onsuccess=()=>{db.close();resolve(r.result||null)};r.onerror=()=>{db.close();reject(r.error)}})}
async function writeStudyDB(v){const db=await openStudyDB();return new Promise((resolve,reject)=>{const tx=db.transaction(DB_STORE,'readwrite');tx.objectStore(DB_STORE).put(v,DB_KEY);tx.oncomplete=()=>{db.close();resolve(true)};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||new Error('Veritabanı işlemi iptal edildi.'))}})}
function queueStudyDBWrite(v){const write=dbWriteQueue.catch(()=>undefined).then(()=>writeStudyDB(v));dbWriteQueue=write.catch(()=>undefined);return write}

async function putLocalFile(id,blob){const db=await openStudyDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(blob,id);tx.oncomplete=()=>{db.close();resolve(true)};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||new Error('Veritabanı işlemi iptal edildi.'))}})}
async function getLocalFile(id){const db=await openStudyDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readonly'),r=tx.objectStore('files').get(id);r.onsuccess=()=>{db.close();resolve(r.result||null)};r.onerror=()=>{db.close();reject(r.error)}})}
async function deleteLocalFile(id){const db=await openStudyDB();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(id);tx.oncomplete=()=>{db.close();resolve(true)};tx.onerror=()=>{db.close();reject(tx.error)};tx.onabort=()=>{db.close();reject(tx.error||new Error('Veritabanı işlemi iptal edildi.'))}})}


const SAFE_NOTE_TAGS=new Set(['P','BR','H1','H2','H3','UL','OL','LI','STRONG','B','EM','I','U','BLOCKQUOTE','HR','DIV','SPAN']);
function sanitizeNoteHTML(input=''){
 if(typeof window==='undefined'||!input)return '';
 const doc=new DOMParser().parseFromString(String(input),'text/html');
 const clean=node=>{[...node.childNodes].forEach(child=>{if(child.nodeType===Node.COMMENT_NODE){child.remove();return}if(child.nodeType!==Node.ELEMENT_NODE)return;if(!SAFE_NOTE_TAGS.has(child.tagName)){clean(child);child.replaceWith(...child.childNodes);return}for(const attr of [...child.attributes])child.removeAttribute(attr.name);clean(child)})};
 clean(doc.body);return doc.body.innerHTML;
}
function load(){try{const raw=localStorage.getItem(KEY)??localStorage.getItem(LEGACY_KEY);const v=raw?JSON.parse(raw):null;if(v&&Array.isArray(v.courses)&&Array.isArray(v.notes)&&Array.isArray(v.tasks))return {...blank(),...v,trash:Array.isArray(v.trash)?v.trash:[],focusSessions:Array.isArray(v.focusSessions)?v.focusSessions:[],documents:Array.isArray(v.documents)?v.documents:[],exams:Array.isArray(v.exams)?v.exams:[],gradeItems:Array.isArray(v.gradeItems)?v.gradeItems:[]};}catch(e){console.error('StudyMate verileri okunamadı:',e)}return blank()}
