e(()=>{try{return JSON.parse(localStorage.getItem('studymate.autoBackups')||'[]')}catch{return []}}),[introOpen,setIntroOpen]=useState(()=>localStorage.getItem('studymate.introDone')!=='yes'),[introStep,setIntroStep]=useState(0),[docPreview,setDocPreview]=useState(null),[docUrl,setDocUrl]=useState(''),[docQuery,setDocQuery]=useState(''),[docCourse,setDocCourse]=useState('all'),[docBusy,setDocBusy]=useState(false),[gradeCourse,setGradeCourse]=useState(''),[gradeInputs,setGradeInputs]=useState({}),[examForm,setExamForm]=useState({title:'',type:'Vize',date:dateISO(new Date()),time:'10:00',courseId:'',location:'',notes:''}),[editExamId,setEditExamId]=useState(null),[gradeForm,setGradeForm]=useState({name:'Vize',weight:40,score:''}),[gradeTarget,setGradeTarget]=useState(60),[pdfPageNotes,setPdfPageNotes]=useState(''),[pdfPage,setPdfPage]=useState(1)
 useEffect(()=>{let live=true;(async()=>{try{const saved=await readStudyDB();if(!live)return;if(saved&&Array.isArray(saved.tasks)&&Array.isArray(saved.notes))setData({...blank(),...saved,flashcards:[]});else{const legacy=load();await writeStudyDB({...legacy,flashcards:[]});if(live)setData({...legacy,flashcards:[]})}}catch(e){console.warn('IndexedDB unavailable; using local fallback',e)}finally{if(live)setDbReady(true)}})();return()=>{live=false}},[]);
