 useEffect(()=>{if(!dbReady)return;const stamp='studymate.reminder.'+dateISO(new Date());if(localStorage.getItem(stamp))return;const now=dateISO(new Date());const due=data.tasks.filter(t=>!(t.done||t.status==='done')&&t.date&&t.date<=now);if(!due.length)return;const item={id:uid(),title:'Görev hatırlatması',body:due.length+' gecikmiş veya bugün teslim edilecek görevin var.',at:Date.now(),read:false};setNotifications(n=>[item,...n].slice(0,80));try{if('Notification' in window&&Notification.permission==='granted')new Notification('StudyMate',{body:item.body,icon:'./studymate-mark.png'})}catch{}localStorage.setItem(stamp,'1')},[dbReady,data.tasks]);
 useEffect(()=>{const handler=e=>{const target=e.target;const isTyping=!!(target?.isContentEditable||['INPUT','TEXTAREA','SELECT'].includes(target?.tagName)||target?.closest?.('[contenteditable="true"]'));if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!isTyping){e.preventDefault();setPaletteOpen(v=>!v);setPaletteQuery('')}if(e.key==='Escape'){setPaletteOpen(false);setWidgetMenu(false);setNotificationOpen(false)}if(!isTyping&&!e.ctrlKey&&!e.metaKey&&!e.altKey){if(e.key.toLowerCase()==='n'){e.preventDefault();open('note')}if(e.key.toLowerCase()==='t'){e.preventDefault();open('task')}}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[]);
